score = int(input("Баллы: "))

if score >= 90:
    print("Отлично")
elif score >= 60:
    print("Зачёт")
else:
    print("Нужно повторить")

age = int(input("Возраст: "))
has_ticket = input("Есть билет? да/нет: ") == "да"

if age >= 18 and has_ticket:
    print("Проходите")
else:
    print("Вход запрещён")

